import { ok, fail } from './result.js';
import { daysBetween, isValidDate } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Generate a report of overdue invoices as of a specific date.
 * @param {Array} invoices
 * @param {string} asOf - A date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  // Validate asOf date
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  // Filter overdue invoices (status issued or partially_paid, dueDate before asOf)
  const overdue = invoices
    .filter(
      (inv) =>
        (inv.status === 'issued' || inv.status === 'partially_paid') &&
        inv.dueDate < asOf,
    )
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue); // Most overdue first

  return ok(overdue);
}

/**
 * Generate a VAT summary from invoices.
 * @param {Array} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const byRate = {}; // Map of rate -> {base, vat}

  invoices
    .filter(
      (inv) =>
        inv.status === 'issued' ||
        inv.status === 'partially_paid' ||
        inv.status === 'paid',
    )
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;

        // Calculate line total and discount
        const lineTotal = line.qty * line.unitPrice;
        const discount = roundCents(
          lineTotal * (line.discountPercent || 0) / 100,
        );
        const base = lineTotal - discount;
        const vat = roundCents((base * rate) / 100);

        // Add to accumulator
        if (!byRate[rate]) {
          byRate[rate] = { base: 0, vat: 0 };
        }
        byRate[rate].base += base;
        byRate[rate].vat += vat;
      });
    });

  // Convert to sorted array, high to low
  return Object.entries(byRate)
    .map(([rate, { base, vat }]) => ({
      rate: parseFloat(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * @param {{ dueDate: string, status: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - A date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  // Check if invoice is overdue
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  // Calculate days overdue and amount due
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);

  // Late fee: 0.04% per day of the amount due
  return roundCents((amountDue * 0.04 * daysOverdue) / 100);
}

