  // 5 days overdue: Fee = roundCents(1034550 * 0.04 * 5 / 100) = roundCents(2069.1) = 2069
  const fee5 = lateFee(issued.value, '2026-10-26');
  // 10 days overdue: Fee = roundCents(1034550 * 0.04 * 10 / 100) = roundCents(4138.2) = 4138
  const fee10 = lateFee(issued.value, '2026-10-31');
  // 20 days overdue: Fee = roundCents(1034550 * 0.04 * 20 / 100) = roundCents(8276.4) = 8276
  const fee20 = lateFee(issued.value, '2026-11-10');
  assert.equal(fee5, 2069);
  assert.equal(fee10, 4138);
  assert.equal(fee20, 8276);
});

