  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const partial = recordPayment(issued2.value, { amount: 50000, date: '2026-10-15' });
  // Both invoices included: total base = 90250 + 45125 = 135375
