    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  // Both with 5% tier discount
  // Invoice 1: 10 * 9500 = 95000, discount 4750, base = 90250
  // Invoice 2: 5 * 9500 = 47500, discount 2375, base = 45125
  // Total: base = 135375
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 135375);
});

test('vatSummary handles multiple VAT rates', () => {
