  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);
  const result = dashboard([issued1.value, issued2.value, issued3.value], '2026-10-31');
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert.equal(result.topCustomers[1].customerId, 'C-002');
  assert.equal(result.topCustomers[2].customerId, 'C-003');
});

test('dashboard top customers sorted by due amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);
  const result = dashboard([issued1.value, issued2.value, issued3.value], '2026-10-31');
  // C-002 has most due (50+ euro), then C-003 (25+ euro), then C-001 (4+ euro)
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  assert.equal(result.topCustomers[1].customerId, 'C-003');
  assert.equal(result.topCustomers[2].customerId, 'C-001');
  assert(result.topCustomers[0].due > result.topCustomers[1].due);
  assert(result.topCustomers[1].due > result.topCustomers[2].due);
});

test('dashboard limits to top 3 customers', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: i }],
    });
    invoices.push(issueInvoice(inv.value, invoices.map((_, idx) => `INV-2026-000${idx + 1}`)).value);
  }
  const result = dashboard(invoices, '2026-10-31');
  assert.equal(result.topCustomers.length, 3);
});

test('dashboard excludes paid and draft invoices from outstanding', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const paid = recordPayment(issued2.value, { amount: 57475, date: '2026-10-15' });
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  const result = dashboard([issued1.value, paid.value, draft.value], '2026-10-31');
  // Only issued1 counts (57475 = 47500 + 9975 VAT)
  assert.equal(result.outstanding, 57475);
});

test('dashboard with partial payments in top customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const partial = recordPayment(issued1.value, { amount: 25000, date: '2026-10-15' });
  const result = dashboard([partial.value], '2026-10-31');
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  // C-002 standard tier, qty:10 with no discount gets bulk discount 2.5%
  // lineTotal = 95000, bulkDiscount = 2375, base = 92625, VAT = 19451
  // total = 112076, due = 112076 - 25000 = 87076
  assert.equal(result.topCustomers[0].due, 87076);
});

